interface A {
    default String name() { return "A"; }
}

interface B {
    default String name() { return "B"; }
}

class C implements A, B {
    @Override
    public String name() {
        return A.super.name() + B.super.name();
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println(new C().name());
    }
}

